      "id": "arxiv:2611.03555v1",
      "title": "MCP Tool Poisoning in Agentic AI Frameworks: A Cross-Framework Measurement Study",
      "url": "https://arxiv.org/abs/2611.03555v1",
      "pdfUrl": "https://arxiv.org/pdf/2611.03555v1",
      "source": "arXiv",
      "points": 0,
